<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;
use App\Models\Booking;
use App\Models\Vehicle;
use Illuminate\Http\Request;
use Illuminate\Support\Str;
use Illuminate\Support\Facades\DB;
class BookingController extends Controller {
 public function index(Request $r){$q=Booking::with(['customer:id,name,phone','vehicle:id,name,registration_number']);if($r->filled('status'))$q->where('status',$r->status);return $q->latest()->paginate(20);}
 public function store(Request $r){$d=$r->validate(['customer_id'=>'required|exists:customers,id','vehicle_id'=>'required|exists:vehicles,id','start_date'=>'required|date','end_date'=>'required|date|after_or_equal:start_date','pickup_location'=>'nullable|string|max:250','return_location'=>'nullable|string|max:250','status'=>'required|in:pending,confirmed,active,completed,cancelled','notes'=>'nullable|string|max:2000']);return DB::transaction(function()use($d,$r){$v=Vehicle::whereKey($d['vehicle_id'])->lockForUpdate()->firstOrFail();if($v->status==='maintenance')return response()->json(['message'=>'Vehicle is under maintenance.'],422);$conflict=Booking::where('vehicle_id',$v->id)->whereNotIn('status',['cancelled','completed'])->whereDate('start_date','<=',$d['end_date'])->whereDate('end_date','>=',$d['start_date'])->exists();if($conflict)return response()->json(['message'=>'Vehicle has an overlapping booking.'],422);$days=max(1,\Carbon\Carbon::parse($d['start_date'])->diffInDays(\Carbon\Carbon::parse($d['end_date'])));$b=Booking::create($d+['booking_number'=>'YRS-'.strtoupper(Str::random(8)),'daily_rate'=>$v->daily_rate,'days'=>$days,'total_amount'=>$days*(float)$v->daily_rate,'created_by'=>$r->user()->id]);if($d['status']==='active')$v->update(['status'=>'rented']);return response()->json($b->load(['customer','vehicle']),201);});}
 public function show(Booking $booking){return $booking->load(['customer','vehicle']);}
 public function update(Request $r,Booking $booking){$d=$r->validate(['customer_id'=>'sometimes|required|exists:customers,id','vehicle_id'=>'sometimes|required|exists:vehicles,id','start_date'=>'sometimes|required|date','end_date'=>'sometimes|required|date|after_or_equal:start_date','pickup_location'=>'nullable|string|max:250','return_location'=>'nullable|string|max:250','status'=>'sometimes|required|in:pending,confirmed,active,completed,cancelled','notes'=>'nullable|string|max:2000']);$vid=$d['vehicle_id']??$booking->vehicle_id;$start=$d['start_date']??$booking->start_date->toDateString();$end=$d['end_date']??$booking->end_date->toDateString();$conflict=Booking::where('vehicle_id',$vid)->where('id','!=',$booking->id)->whereNotIn('status',['cancelled','completed'])->whereDate('start_date','<=',$end)->whereDate('end_date','>=',$start)->exists();if($conflict)return response()->json(['message'=>'Vehicle has an overlapping booking.'],422);$v=Vehicle::findOrFail($vid);$days=max(1,\Carbon\Carbon::parse($start)->diffInDays(\Carbon\Carbon::parse($end)));$d['days']=$days;$d['daily_rate']=$v->daily_rate;$d['total_amount']=$days*(float)$v->daily_rate;$booking->update($d);return $booking->fresh()->load(['customer','vehicle']);}
 public function destroy(Booking $booking){if($booking->status==='active')return response()->json(['message'=>'Cannot delete an active rental.'],422);$booking->delete();return response()->json(['message'=>'Deleted']);}
 public function status(Request $r,Booking $booking){$d=$r->validate(['status'=>'required|in:pending,confirmed,active,completed,cancelled']);if($d['status']==='active'){$conflict=Booking::where('vehicle_id',$booking->vehicle_id)->where('id','!=',$booking->id)->whereNotIn('status',['cancelled','completed'])->whereDate('start_date','<=',$booking->end_date)->whereDate('end_date','>=',$booking->start_date)->exists();if($conflict)return response()->json(['message'=>'Cannot activate because of a conflicting booking.'],422);}$booking->update($d);if($d['status']==='active')$booking->vehicle()->update(['status'=>'rented']);elseif(in_array($d['status'],['completed','cancelled'])&&!Booking::where('vehicle_id',$booking->vehicle_id)->where('status','active')->exists())$booking->vehicle()->update(['status'=>'available']);return $booking->fresh()->load(['customer','vehicle']);}
}
